actions.handler:
() => {
    const val = id => document.getElementById(id)?.value?.trim() || '';
    A?.llm.saveConfig({ baseUrl: val('devcLlmUrl'), apiKey: val('devcLlmKey'), model: val('devcLlmModel') });
    UI.log('[[icon:tools]] LLM 配置已保存（仅本机 localStorage）', 'sys');
    render();
  }

(d) => {
    // jump 成功时 page.enter 已在控制台同层开出目标页（控制台页被顶替=已关闭）；
    // 此时再 hideOverlay 会把新页的动作表一并清掉（INFRA-02），跳转失败才重绘本页。
    if (jump(d.page)) return;
    render();
  }

(d) => {
    if (d.confirm !== '1') {
      // 两步确认：首点变「确认清空？」，与危险操作同款防误触
      const btn = document.querySelector('#ovBody [data-act="dataClear"]');
      if (btn) { btn.dataset.confirm = '1'; btn.textContent = '确认清空？'; btn.classList.add('arm'); }
      return;
    }
    clearRuns();
    UI.log('[[icon:tools]] 跑局记录已清空', 'sys');
    render();
  }

(d) => {
      const g = SDT.game;
      const group = (g.ownedCards || []).filter(o => o.card && !o.safe && cardIdentityKey(o.card) === d.cardKey);
      if (!group.length) return;
      const name = group[0].card.name;
      const free = Math.max(0, ((g.safeCap && g.safeCap()) || 0) - ((g.safeUsed && g.safeUsed()) || 0));
      if (group.length > free) { UI.log(`[[icon:lock]] 安全格空位不足（${free} 格）——存不进「${esc(name)}」×${group.length}`, 'warn'); SDT.Sound.sfx('deny'); return; }
      group.forEach(o => { o.safe = true; });
      UI.log(`[[icon:lock]] 【${esc(name)}】×${group.length} 已存入安全格（撤离失败时安全运回）`, 'sys');
      if (g.saveGame) g.saveGame();
      renderBattleBag(getSnapshot());
    }

(d) => {
        const el = document.querySelector(`.bt-card[data-act="btDiscover"][data-i="${d.i}"]`);
        if (el) { discoverSrcRect = uiRect(el); }   // 布局口径：消费端喂 transform
        pickDiscover(d.i);
      }

(d) => {
      if (Date.now() - aimPlayedAt < 300) return;   // 指向松手刚打出，忽略残留 click
      if (infusingNow) return toggleInfusePick(d.uid);
      const el = [...document.querySelectorAll('.sts-hand .bt-card')].find(x => x.dataset.uid === d.uid);
      // 指向性卡支持点击选中，再点击目标；无目标卡保持点击即出牌。
      if (el && el.dataset.aim && el.dataset.side !== 'any') return selectCardByClick(d.uid);
      showCardBlockReason(d.uid);
      play(d.uid);
    }

() => {
      UI.showOverlay('[[icon:gear]] 战斗设置', `
        <div class="bt-settings">
          <label class="chk"><input type="checkbox" id="btSetMusic" ${SDT.Sound.musicMuted ? '' : 'checked'}> 背景音乐</label>
          <label class="chk"><input type="checkbox" id="btSetSfx" ${SDT.Sound.sfxMuted ? '' : 'checked'}> 音效</label>
          <label class="chk"><input type="checkbox" id="btSetShake" ${storeGet('sdt-reduce-shake') === '1' ? '' : 'checked'}> 屏幕震动反馈</label>
          <label class="chk"><input type="checkbox" id="btSetPace" ${getPace() === 2 ? 'checked' : ''}> 2× 战斗节奏（敌方行动加速）</label>
          <p class="ov-note">完整设置可在基地 / 标题页打开。关闭后回到战斗。</p>
          <div class="ov-btns"><button class="ov-btn ok" data-act="btSettingsBack">[[icon:cross]] 返回战斗</button></div>
        </div>`, true);
      // 迭代评审 09-20：删除无参 setDucked()——它被 setDucked 内部 !!v 强转成 false，
      // 战斗中关音乐会静默解除侧链压低；setMusicMuted 内部已走 syncBgm，无需额外调用
      const syncMusic = (on) => { SDT.Sound.setMusicMuted(!on); };
      document.getElementById('btSetMusic').addEventListener('change', (e) => syncMusic(e.target.checked));
      document.getElementById('btSetSfx').addEventListener('change', (e) => { SDT.Sound.setSfxMuted(!e.target.checked); });
      document.getElementById('btSetShake').addEventListener('change', (e) => { storeSet('sdt-reduce-shake', e.target.checked ? '0' : '1'); });
      // 2× 演示倍率（迭代评审 09-20）：单一倍率同步缩放步进/序列帧/前摇/飘字四处时长（battle.pace.js）
      document.getElementById('btSetPace').addEventListener('change', (e) => { setPace(e.target.checked ? 2 : 1); });
      UI.act('btSettingsBack', () => render());
    }

() => {
      if (getSnapshot().opts.isBoss) {
        UI.log('[[icon:lock]] BOSS 战不可撤离——击败首脑或战败即终局', 'warn');
        SDT.Sound.sfx('deny');
        return;
      }
      // 撤离=判负不可逆：两步确认防误触（同设置弹窗危险钮模式，2.6 秒后自动还原）。
      // W2-01（2026-09-27 R2）：arm 态此前只换文本——.arm 类全 css 无样式（评审实锤
      // 「无色彩升级」），不可逆钮埋在低危排里第二击即判负，危险度必须映射到视觉
      // 维度（透镜 #66）。battle.css 冻结、独立片 include 管线未通 → 模块级注入
      // 样式表（head 内 .ov-btn.ghost.arm 规则，!important 压 winter 底式）；实测
      // 异步环节可能剥 style 属性但不动 class，故样式挂类、内联仅作双保险。
      const btn = document.querySelector('#ovBody [data-act="btFlee"]');
      if (!btn || btn.dataset.confirm) { surrender(); return; }   // 玩法定版：主动撤离=本局失败（烟雾弹走 fleeBattle 豁免）
      const prev = btn.innerHTML;
      const prevStyle = btn.getAttribute('style') || '';   // 模板自带的 margin:0 12px（危险钮间距分级）还原基准
      btn.dataset.confirm = '1';
      btn.innerHTML = SDT.Icons.rich('[[icon:runner]] 确认撤离？');
      btn.classList.add('arm');
      Object.assign(btn.style, {
        color: '#f6ddd6', background: '#61241f', borderColor: '#c96a5c',
        boxShadow: '0 0 10px rgba(201,106,92,.45), inset 0 0 8px rgba(120,40,32,.5)',
        transform: 'scale(1.07)',
      });
      setTimeout(() => {
        if (btn.isConnected) {
          delete btn.dataset.confirm; btn.classList.remove('arm'); btn.innerHTML = prev;
          btn.setAttribute('style', prevStyle);
        }
      }, 2600);
    }

() => {
      if (getSnapshot().opts.isBoss) {
        UI.log('[[icon:lock]] BOSS 战为牌库制：道具与资源不参战，背包不可打开', 'warn');
        SDT.Sound.sfx('deny');
        return;
      }
      openBagCmd();
    }

() => {
      if (Date.now() - aimPlayedAt < 300) return;   // 拖拽松手刚砸完，忽略残留 click（同药水栏口径）
      bagSlam();
    }

(d) => {
      if (Date.now() - aimPlayedAt < 300) return;   // 拖拽刚松手，忽略残留 click
      usePotion(d.uid);
    }

() => {
      closeZoom();
      // 2026-09-06 #10：3 张员工通行证B合成 1 张员工通行证A
      const golds = game.ownedCards.filter(x => x.card.id === 'tt-token-gold').slice(0, 3);
      if (golds.length < 3) { UI.log('员工通行证B不足 3 张，无法合成', 'warn'); return; }
      const goldIds = new Set(golds.map(g => g.uid));
      game.ownedCards = game.ownedCards.filter(x => !goldIds.has(x.uid));
      const color = SDT.Cards.all().find(c => c.id === 'tt-token-color');
      if (color) game.ownedCards.push({ uid: newUid(), card: { ...color } });
      UI.log('[[icon:sparkles]] 合成成功：3 张员工通行证B → 1 张<b>员工通行证A</b>', 'loot');
      saveGame();
      showBackpack(true);
    }

() => {
      closeZoom();
      // 2026-09-09 Q6 老板定向：隐藏计数器碎片——集齐 2 枚碎片 + 员工通行证A → 合成员工通行证A
      if ((game.fragments || 0) < 2) { UI.log('员工通行证A碎片不足 2 枚，无法合成', 'warn'); return; }
      game.ownedCards.splice(game.ownedCards.indexOf(o), 1);
      game.fragments -= 2;
      const token = SDT.Cards.all().find(c => c.id === 'cmtmvq6ss84l');
      if (token) game.ownedCards.push({ uid: newUid(), card: { ...token } });
      UI.log('[[icon:sparkles]] 合成成功：员工通行证A + 2 枚碎片 → 1 张<b>员工通行证A</b>（使用后获取本职业能力卡）', 'loot');
      saveGame();
      showBackpack(true);
    }

(d) => {
      const stack = bagSpellStacks().find(st => st.card.name === d.name);
      if (!stack) return;
      // 整叠存入也受 3 张上限：已有数量 + 本次堆数超过即拒收（此前只查已有 ≥3，
      // 整叠 3 张可与已有 2 张叠成 5/3，09-30 深审 ROOT-04）
      if (stored().length + stack.count > 3) {
        UI.log(`[[icon:cards]] 锦囊装不下整叠：已有 ${stored().length}/3 张，本次 ${stack.count} 张`, 'warn');
        SDT.Sound.sfx('deny');
        return;
      }
      stack.uids.forEach(uid => { const o = game.ownedCards.find(x => x.uid === uid); if (o) { o.pouchOf = POUCH_ID; o.stored = 1; } });
      UI.log(`[[icon:cards]] 【<b>${esc(stack.card.name)}</b>】存入法师锦囊`, 'ok');
      saveGame();
      render();
    }

(d) => {
      const stack = storedStacks().find(st => st.card.name === d.name);
      if (!stack) return;
      game.ownedCards.forEach(x => { if (x.pouchOf === POUCH_ID && x.card.name === d.name) { delete x.pouchOf; delete x.stored; } });
      UI.log(`[[icon:cards]] 【<b>${esc(stack.card.name)}</b>】已从锦囊取出`, 'ok');
      saveGame();
      render();
    }

(d) => {
      const stack = bagResStacks().find(st => st.card.name === d.name);
      if (!stack) return;
      if (storedN() + stack.count > cap) {
        UI.log(`[[icon:gem]] 珍珠盒放不下了（${storedN()}/${cap} 张）——先取出一些`, 'warn');
        SDT.Sound.sfx('deny');
        return;
      }
      stack.uids.forEach(uid => { const o = game.ownedCards.find(x => x.uid === uid); if (o) o.stored = 1; });
      UI.log(`[[icon:gem]] 【<b>${esc(stack.card.name)}</b>】×${stack.count} 存入珍珠盒——腾出 1 个背包格`, 'ok');
      SDT.Sound.sfx('gain');
      saveGame();
      render();
    }

(d) => {
      const stack = storedStacks().find(st => st.card.name === d.name);
      if (!stack) return;
      // 取出按「格数增量」检查：整叠 9 张按 3 张/格需 3 格，只查 1 个空格会越界
      // （09-30 深审 ROOT-03）；同名合并口径与 moveStackSafe 一致
      const cap = game.stackCapOf(stack.card);
      const sameBag = game.ownedCards.filter(x => !x.safe && !x.stored && x.card.name === stack.card.name).length;
      const delta = Math.ceil((sameBag + stack.count) / cap) - Math.ceil(sameBag / cap);
      if (usedSlots() + delta > bagCap()) {
        UI.log(`[[icon:bag]] 背包放不下：本次整叠还需 ${delta} 格（现 ${usedSlots()}/${bagCap()} 格），先腾出空间`, 'warn');
        SDT.Sound.sfx('deny');
        return;
      }
      // 只解除珍珠盒自己的标记：锦囊法术（pouchOf）不在盒中，跨容器取出会留下双份归属
      game.ownedCards.forEach(x => { if (x.stored && !x.pouchOf && x.card.name === stack.card.name) delete x.stored; });
      UI.log(`[[icon:bag]] 【<b>${esc(stack.card.name)}</b>】×${stack.count} 从珍珠盒取出，回到背包`, 'ok');
      saveGame();
      render();
    }

(d) => {
      const st = cardStacks(d.safe === '1').find(s => s.card.name === d.name);
      if (!st) return;
      const usable = d.safe !== '1' && st.card.type === '道具';
      // 珍珠盒/法师锦囊：点击直接打开容器界面（2026-09-16 留言）
      const isPearl = st.card.id === 'tt2-pearlbox' && d.safe !== '1';
      const isPouch = st.card.id === 'tt7-stratagem' && d.safe !== '1';
      let containerBtn = '';
      if (isPearl) containerBtn = '<div class="ov-btns"><button class="ov-btn ok" data-act="pearlStoreZoom">[[icon:gem]] 打开珍珠盒</button></div>';
      if (isPouch) containerBtn = '<div class="ov-btns"><button class="ov-btn ok" data-act="pouchStoreZoom">[[icon:cards]] 打开锦囊（存放法术 ×3）</button></div>';
      // 点击移动（2026-09-16 留言）：背包卡可移入安全格、安全格卡可移回背包（不必拖拽）
      const isShaStack = st.card.name === (SDT.Cards.SHA && SDT.Cards.SHA.name);
      const moveBtn = d.safe === '1'
        ? '<div class="ov-btns"><button class="ov-btn" data-act="zoomMoveToBag">[[icon:bag]] 移回背包</button></div>'
        : (isShaStack ? '' : '<div class="ov-btns"><button class="ov-btn" data-act="zoomMoveToSafe">[[icon:lock]] 移入安全格</button></div>');
      UI.showCardZoom(st.card, {
        footer: `${containerBtn}
          ${usable ? '<div class="ov-btns"><button class="ov-btn ok" data-act="useDetailCard">使用这张道具</button></div>' : ''}
          ${moveBtn}
          <p class="ov-note">${d.safe === '1' ? '[[icon:lock]] 安全格 · 可拖回背包或点击「移回背包」' : '按住拖动整理顺序 · 双击翻看卡背 · 可点击「移入安全格」'}</p>`,
      });
      if (d.safe === '1') {
        UI.act('zoomMoveToBag', () => {
          document.getElementById('cardZoom')?.querySelector('.cz-backdrop')?.click();
          moveStackSafe(st.card.name, false);
        });
      } else if (!isShaStack) {
        UI.act('zoomMoveToSafe', () => {
          document.getElementById('cardZoom')?.querySelector('.cz-backdrop')?.click();
          moveStackSafe(st.card.name, true);
        });
      }
      // 特写收起助手：与 showBagCardDetail 里的同名助手同体（动作前先模拟点背景收回特写）
      const closeCardZoom = () => document.getElementById('cardZoom')?.querySelector('.cz-backdrop')?.click();
      if (isPearl) UI.act('pearlStoreZoom', () => { closeCardZoom(); openPearlStore(); });
      if (isPouch) UI.act('pouchStoreZoom', () => { closeCardZoom(); openPouchStore(); });
      if (usable) UI.act('useDetailCard', () => {
        document.getElementById('cardZoom')?.querySelector('.cz-backdrop')?.click();
        useOwnedCard(st.uids[0]);
      });
    }

(d) => {
      const item = MECH_ALL.find(it => it.k === d.k);
      if (!item) return;
      draft.desc = mechToggle(draft.desc, item);
      if (draft.desc.length > 100) { UI.log('描述超过 100 字上限，最后一条词条放不下了', 'warn'); mechSyncUI(); return; }
      Sfx.tick();
      mechSyncUI();
    }

(d) => {
      draft.type = d.t;
      if (!DMG_TYPES.includes(d.t)) draft.dmg = 0;
      else if (!SDT.Cards.DMG_TYPE_META[draft.dmgType]) draft.dmgType = d.t === '法术' ? 'spell' : 'attack';
      Sfx.tick(); syncDesignerForm();
    }

async () => {
      try { await navigator.clipboard.writeText(json); UI.log('卡牌 JSON 已复制', 'ok'); }
      catch { UI.log('复制失败，请手动全选复制', 'warn'); }
    }

() => {
      const blob = new Blob([json], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'sdt-cards.json';
      a.click();
      URL.revokeObjectURL(a.href);
    }

() => {
      if (!CARD_DESIGNER_WRITES_ENABLED) return;
      const ta = document.getElementById('ovImport');
      try {
        const parsed = JSON.parse(ta.value);
        const cards = Array.isArray(parsed) ? parsed : parsed.cards;
        if (!Array.isArray(cards)) throw new Error('缺少 cards 数组');
        for (const c of cards) {
          if (!c.name) continue;
          SDT.Cards.upsert({
            id: c.id, name: String(c.name).slice(0, 12),
            cost: [0, 1, 2, 3, 4, 5].includes(+c.cost) ? +c.cost : 1,
            rarity: RARITIES.includes(c.rarity) ? c.rarity : '古朴',
            type: TYPES.includes(c.type) ? c.type : '武术',
            dmg: Math.max(0, Math.min(99, +c.dmg || 0)),
            dmgType: SDT.Cards.DMG_TYPE_META[c.dmgType] ? c.dmgType : undefined,
            draw: Math.max(0, Math.min(99, +c.draw || 0)) || undefined,
            infuse: Math.max(0, Math.min(99, +c.infuse || 0)) || undefined,
            heal: Math.max(0, Math.min(99, +c.heal || 0)) || undefined,
            armor: Math.max(0, Math.min(99, +c.armor || 0)) || undefined,
            desc: String(c.desc || '').slice(0, 100),
            value: Math.max(0, Math.min(99, +c.value || 0)),
            sellable: typeof c.sellable === 'boolean' ? c.sellable : undefined,
          });
        }
        UI.log('卡牌导入完成', 'ok');
        deps.openCardLibrary();
      } catch (err) { UI.log('导入失败：' + err.message, 'warn'); }
    }

(d) => {
    if (d.filter === 'tab') libFilter.tab = '全部';
    else if (d.filter === 'rar') libFilter.rar = '全部';
    else if (d.filter === 'cls') libFilter.cls = '全部';
    else if (d.filter === 'q') libFilter.q = '';
    syncLibFilterUI(); renderLibGrid();
  }

(d) => {
    if (!CARD_DESIGNER_WRITES_ENABLED) return;
    const card = SDT.Cards.all().find(c => c.id === (d.card || d.id));
    if (card) openCardDesigner(card);
  }

(d, trigger) => {
    const card = libCards.find(c => c.id === d.card);
    // 快门声+白闪是照相馆的「取照片」仪式（sfx('shutter')，静音/音效开关由 Sound 统一把关）
    SDT.Sound.sfx('shutter');
    if (card) {
      const active = trigger?.matches?.('[data-photo-zoom-source]')
        ? trigger
        : (document.activeElement?.matches?.(`[data-photo-zoom-source][data-card="${d.card}"]`) ? document.activeElement : null);
      const from = active?.classList.contains('studio-zoom') && libSelectedId === card.id
        ? document.querySelector('.photo-studio-v3 .studio-preview-paper')
        : (active?.querySelector('.studio-photo-paper') || document.querySelector(`#libGrid .lib-cardwrap[data-card="${d.card}"] .studio-photo-paper`));
      // 同步墙上选中态/选片台内容，不重建网格、不重置筛选或滚动位置。
      if (libSelectedId !== card.id) setLibSelection(card.id);
      const returnFocus = active?.classList.contains('studio-zoom') && !active.isConnected
        ? document.querySelector('.photo-studio-v3 .studio-zoom')
        : active;
      UI.showCardZoom(card, {
        from,
        returnFocus,
        presentation: 'photo',
        photoNumber: photoNo(card.id),
        note: photoNoteFor(card),
        noteLabel: '备注',
        noteEditable: true,
        notePlaceholder: PHOTO_NOTE_PLACEHOLDER,
        onNoteSave: value => {
          const saved = savePhotoNote(card, value);
          if (libSelectedId === card.id) {
            const preview = document.getElementById('libPreview');
            const oldNote = preview?.querySelector('.pv-note');
            const note = photoNoteFor(card);
            const noteHTML = note ? `<div class="pv-note"><b>备注</b>${esc(note)}</div>` : '';
            if (oldNote) oldNote.outerHTML = noteHTML;
            else if (noteHTML) preview?.querySelector('.pv-nav')?.insertAdjacentHTML('beforebegin', noteHTML);
          }
          return saved;
        },
      });
    }
  }

(d) => {
    if (!CARD_DESIGNER_WRITES_ENABLED) return;
    const btn = [...document.querySelectorAll('.card-library-page [data-act="delCard"][data-id]')].find(el => el.dataset.id === d.id);
    if (btn && !btn.dataset.confirm) {
      btn.dataset.confirm = '1'; btn.textContent = '确认删除？'; btn.classList.add('arm');
      setTimeout(() => {
        if (btn.isConnected) { delete btn.dataset.confirm; btn.textContent = '删除'; btn.classList.remove('arm'); }
      }, 2600);
      return;
    }
    const card = libCards.find(c => c.id === d.id);
    SDT.Cards.remove(d.id);
    Sfx.tick();
    UI.log(`[[icon:trash]] 已删除卡牌【<b>${esc(card ? card.name : '')}</b>】`, 'warn');
    renderCardLibrary();
  }

() => {
    const blob = new Blob([exportNotes()], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'card-notes.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    UI.log('[[icon:download]] 备注已导出为 card-notes.json，回填 data/ 即同步进数据库', 'ok');
  }

(d) => {
      if (!SDT.Base.setPet(d.id)) return;
      Sfx.tick();
      const pet = SDT.Base.petById(d.id);
      UI.log(`[[icon:paw]] 本局携带宠物<b>「${esc(pet.name)}」</b>：${esc(pet.desc)}`, 'ok');
      renderDepartPrep();
    }

(d) => {
      const isSha = SDT.Cards.SHA.name === d.name;
      const n = isSha ? MAP.rules.starterSha : (deployPick[d.name] || 0);
      if (n <= 0) return;
