    for (const s of ordered) {
      if (room <= 0) break;
      const take = Math.min(s.count, room);
      selections.push({ name: s.card.name, count: take });
      room -= take;
    }
    const saved = await extractionCommands.updateCards(selections, viewRunId, viewSlot);
    if (!stillThisView()) return;
